from __future__ import annotations
import hashlib, json, os, tempfile
from datetime import datetime, timezone
from importlib.metadata import version
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest().upper()
def atomic_json(path,payload):
 path.parent.mkdir(parents=True,exist_ok=True); fd,tmp=tempfile.mkstemp(prefix=f'.{path.name}.',suffix='.tmp',dir=str(path.parent)); os.close(fd); tmp=Path(tmp)
 try: tmp.write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding='utf-8'); os.replace(tmp,path)
 finally:
  if tmp.exists(): tmp.unlink()
def main()->int:
 v=json.loads((ROOT/'reports/stage5_validation.json').read_text(encoding='utf-8')); p=json.loads((ROOT/'reports/stage5_precedent_report.json').read_text(encoding='utf-8')); e=json.loads((ROOT/'reports/stage5_ecdf_build_report.json').read_text(encoding='utf-8')); a=json.loads((ROOT/'reports/stage5_sc_apply_report.json').read_text(encoding='utf-8')); s4=json.loads((ROOT/'reports/stage4_manifest.json').read_text(encoding='utf-8')); env=json.loads((ROOT/'reports/environment_check.json').read_text(encoding='utf-8'))
 outputs={'reaction_precedent':'data/processed/reaction_precedent.parquet','reference_sc_ecdf_audit':'data/reference/reference_sc_ecdf_audit.parquet','sc_delta_ecdf':'artifacts/sc_delta_ecdf.npz','reaction_sc_normalized':'data/processed/reaction_sc_normalized.parquet'}
 manifest={'stage':5,'status':'PASS','validation_status':'PASS','created_at_utc':datetime.now(timezone.utc).isoformat(),'git_commit':None,'git_commit_reason':'Project directory is not a Git worktree','python_version':env.get('python',{}).get('version'),'package_versions':{'aizynthfinder':env.get('aizynthfinder',{}).get('version'),'rdkit':env.get('rdkit',{}).get('version'),'numpy':env.get('numpy',{}).get('version'),'pandas':env.get('pandas',{}).get('version'),'scikit_learn':version('scikit-learn'),'rxnfp':s4.get('rxnfp_package_version'),'ord_schema':version('ord-schema'),'pyarrow':version('pyarrow'),'scscore':'aizynthfinder.utils.sc_score.SCScore'},'input_files':{'reaction_steps_raw':'data/processed/reaction_steps_raw.parquet','reaction_feasibility':'data/processed/reaction_feasibility.parquet','reaction_sc_raw':'data/processed/reaction_sc_raw.parquet','stage4_manifest':'reports/stage4_manifest.json','stage5_config':'config/stage5_features.yml'},'input_sha256':{'reaction_steps_raw':sha(ROOT/'data/processed/reaction_steps_raw.parquet'),'reaction_feasibility':sha(ROOT/'data/processed/reaction_feasibility.parquet'),'reaction_sc_raw':sha(ROOT/'data/processed/reaction_sc_raw.parquet'),'stage4_manifest':sha(ROOT/'reports/stage4_manifest.json'),'stage5_config':sha(ROOT/'config/stage5_features.yml')},'reference_corpus_sha256':s4['reference_clean_sha256'],'reference_embedding_sha256':s4['rxnfp_embedding_sha256'],'reference_metadata_sha256':s4['reference_metadata_sha256'],'scscore_model_sha256':env['scscore']['sha256'],'rxnfp_model_identity':{'package':s4['rxnfp_package_version'],'model_name':s4['rxnfp_model_name'],'dimension':s4['rxnfp_dimension'],'device':s4['rxnfp_device'],'interpreter':s4['rxnfp_runtime_interpreter']},'tau':0.80,'n0':10,'precedent_mode':p['mode'],'product_rule_version':'single_connected_product_only_v1','ecdf_definition':'#(delta<=x)/N','ecdf_side':'right','ecdf_n_reference_valid':e['n_reference_valid'],'ecdf_n_reference_invalid':e['n_reference_invalid'],'ecdf_invalid_reason_counts':e['invalid_reason_counts'],'ecdf_invalid_duplicate_count_sum':e['invalid_duplicate_count_sum'],'output_files':outputs,'output_sha256':{name:sha(ROOT/path) for name,path in outputs.items()},'validation_report':'reports/stage5_validation.json','validation_status_detail':v,'warnings':['No Stage 6 computations were started.','No Difficulty Model, D_dev, expert labels, or AiZynthFinder changes were performed.']}
 atomic_json(ROOT/'reports/stage5_manifest.json',manifest); print(json.dumps(manifest,indent=2,ensure_ascii=False)); return 0
if __name__=='__main__': raise SystemExit(main())
